# Makes build.nbt from scratch: the parts, then the roof preset (once the shell is built), then move into place.
set -eu
cd "$(dirname "$0")"
MCD="node /Volumes/ext1/swe/repos/minecraft-design/tools/bin/mcd.mjs"

TMP_DIR=$(mktemp -d)
